import {teamName} from './config.js';
import {definitions as D} from './definitions.js';
import {calculatedKeys} from './calculations.js';
const KEY='volleyball-system-v2';
export const newId=prefix=>`${prefix}_${globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+'_'+Math.random().toString(36).slice(2)}`;
export const rawKeys=D.columns.filter(c=>!c.calculated).map(c=>c.key);
export function cleanRaw(raw={}){return Object.fromEntries(Object.entries(raw).filter(([k,v])=>rawKeys.includes(k)&&Number.isSafeInteger(v)&&v>=0));}
export const blankSet=roster=>({players:Object.fromEntries(roster.map(p=>[p.playerId,{}])),opponent:Array(7).fill(0),score:[0,0]});
function seed(){const seen=new Set();const players=D.rosters.flat().filter(p=>!seen.has(p.id)&&seen.add(p.id)).map(p=>({id:newId('player'),name:p.id,number:'',position:p.label.match(/\((.*?)\)/)?.[1]||'S',affiliation:teamName,active:true,memo:''}));return {version:2,players,games:[]};}
function migrate(db,storage){let old;try{old=JSON.parse(storage.getItem('volleyball-record-v1'))}catch{}if(!old?.sets?.length)return db;const rosters=D.rosters.map(rs=>rs.map((p,order)=>({playerId:db.players.find(x=>x.name===p.id).id,name:p.id,position:p.label.match(/\((.*?)\)/)?.[1]||'',number:'',order})));const all=[...new Map(rosters.flat().map(p=>[p.playerId,p])).values()].map((p,order)=>({...p,order}));db.games.push({id:newId('game'),date:'2026-09-30',team:'서산',opponent:'논산계룡',competition:'기존 기록지',type:'기타',location:'',startTime:'',maxSets:3,status:'in_progress',memo:'1차 기록지에서 가져온 기록',roster:all,setRosters:rosters,sets:old.sets.slice(0,3).map((s,i)=>({players:Object.fromEntries(rosters[i].map(p=>[p.playerId,cleanRaw(s.players?.[p.name])])),opponent:Array.from({length:7},(_,j)=>Number.isSafeInteger(s.opponent?.[j])&&s.opponent[j]>=0?s.opponent[j]:0),score:Array.from({length:2},(_,j)=>Number.isSafeInteger(s.score?.[j])&&s.score[j]>=0?s.score[j]:0)})),result:null,createdAt:new Date().toISOString()});return db;}
export function createRepository(storage){let db;let error='';try{const saved=JSON.parse(storage.getItem(KEY));if(saved?.version===2&&Array.isArray(saved.players)&&Array.isArray(saved.games))db=saved;else if(saved)throw Error('저장 데이터 형식을 확인할 수 없습니다.');else{db=migrate(seed(),storage);storage.setItem(KEY,JSON.stringify(db))}}catch(e){error=e.message;db=seed();}
 const renamed=db.games.some(g=>g.team==='부춘')||db.players.some(p=>p.affiliation==='부춘');if(renamed){db.games.forEach(g=>{if(g.team==='부춘')g.team=teamName});db.players.forEach(p=>{if(p.affiliation==='부춘')p.affiliation=teamName});try{storage.setItem(KEY,JSON.stringify(db))}catch{error='팀명 수정 내용을 저장하지 못했습니다. 저장공간을 확인하세요.'}}
 function reload(){try{const latest=JSON.parse(storage.getItem(KEY));if(latest?.version===2&&Array.isArray(latest.players)&&Array.isArray(latest.games))db=latest;}catch{}}
 function persist(){try{storage.setItem(KEY,JSON.stringify(db));error='';return true}catch(e){error='브라우저 저장에 실패했습니다. 현재 화면을 닫지 말고 저장공간을 확인하세요.';return false}}
 return {read:()=>{reload();return structuredClone(db)},getError:()=>error,deletePlayers(ids){reload();const previous=structuredClone(db);const chosen=new Set(ids);const referenced=new Set(db.games.flatMap(g=>[...g.roster.map(p=>p.playerId),...g.sets.flatMap(s=>Object.keys(s.players))]));db.players=db.players.filter(p=>{if(!chosen.has(p.id))return true;if(referenced.has(p.id)){p.deletedAt=new Date().toISOString();p.active=false;return true;}return false;});if(persist())return true;db=previous;return false;},deleteGame(id){reload();const previous=db.games;db.games=db.games.filter(g=>g.id!==id);if(persist())return true;db.games=previous;return false;},deletePlayer(id){reload();const p=db.players.find(p=>p.id===id);if(!p)throw Error('선수를 찾을 수 없습니다.');const referenced=db.games.some(g=>g.roster.some(x=>x.playerId===id)||g.sets.some(set=>Object.hasOwn(set.players,id)));if(referenced){p.deletedAt=new Date().toISOString();p.active=false;}else db.players=db.players.filter(p=>p.id!==id);return {saved:persist(),soft:referenced};},savePlayer(player){reload();const i=db.players.findIndex(p=>p.id===player.id);if(i<0)db.players.push(structuredClone(player));else db.players[i]={...db.players[i],...structuredClone(player)};return persist()},saveGame(game){reload();const copy=structuredClone(game);copy.sets.forEach(s=>{for(const id in s.players)s.players[id]=cleanRaw(s.players[id])});const i=db.games.findIndex(g=>g.id===copy.id);if(i<0)db.games.push(copy);else db.games[i]=copy;return persist()},getGame:id=>{reload();return structuredClone(db.games.find(g=>g.id===id))},retry:persist};}
let singleton;export function installRepository(repo){singleton=repo;}export function repository(){return singleton||(singleton=createRepository(globalThis.localStorage))}
